// Ningua evaluation stub — replaces the AI/speech pipeline locally.
// In production this node calls the STT + AI providers and returns real feedback.
const body = $input.first().json.body || $input.first().json;
const jobId = body.jobId;
const kind = body.kind || 'speaking';
const targetText = body.targetText || '';

const feedback = {
  encouragement: 'Clear and brave — well done.',
  corrections: [
    kind === 'speaking'
      ? 'Lengthen the vowel in "おはよう".'
      : 'Consider the particle は after the topic.',
  ],
  score: 0.78,
  targetText,
};

return [{ json: {
  callback: {
    jobId,
    status: 'completed',
    transcript: kind === 'speaking' ? targetText : null,
    feedback,
  },
} }];
